import Command from "@marko-ui/shadcn/ui/command/command.marko";

static const groups = [
  {
    label: "Suggestions",
    items: [
      { value: "calendar", label: "Calendar" },
      { value: "search-emoji", label: "Search Emoji" },
      { value: "calculator", label: "Calculator" },
    ],
  },
  {
    label: "Settings",
    items: [
      { value: "profile", label: "Profile", shortcut: "⌘P" },
      { value: "billing", label: "Billing", shortcut: "⌘B" },
      { value: "settings", label: "Settings", shortcut: "⌘S" },
    ],
  },
];

<let/selected=null as string | null/>

<div class="flex w-full max-w-[450px] flex-col gap-2">
  <Command
    groups=groups
    placeholder="Type a command or search..."
    class="rounded-lg border shadow-md"
    valueChange=(value) => { selected = value; }
  />
  <span class="text-sm text-muted-foreground">selected: ${selected ?? "none"}</span>
</div>

